# Create the config file using simple PowerShell commands
$configContent = @'
apiVersion: v1
clusters:
- cluster:
    certificate-authority-data: 
    server: https://10.51.100.21:6443
  name: kubernetes
contexts:
- context:
    cluster: kubernetes
    user: kubernetes-admin
  name: kubernetes-admin@kubernetes
current-context: kubernetes-admin@kubernetes
kind: Config
preferences: {}
users:
- name: kubernetes-admin
  user:
    client-certificate-data: 
    client-key-data: 
'@

# Save the file with ASCII encoding (works in all PowerShell versions)
$configContent | Out-File -FilePath $HOME\.kube\homelab-admin.conf -Encoding ascii

# Set the environment variable
$env:KUBECONFIG = "$HOME\.kube\homelab-admin.conf"

# Test it
kubectl get nodes